const rows = $input.all().map(item => item.json);

let html = `<style>
  table { border-collapse: collapse; width: 100%; font-family: sans-serif; }
  th, td { border: 1px solid #ccc; padding: 6px 10px; text-align: left; }
  th { background-color: #f0f0f0; }
</style>
<table>
  <tr>
    <th>Artikelnummer</th>
    <th>Artikelname</th>
    <th>Gesamtbestand</th>
    <th>Bestand in Aufträgen</th>
    <th>Verfügbar</th>
    <th>Mindestbestand</th>
    <th>Differenz</th>
  </tr>`;

for (const row of rows) {
  html += `<tr>
    <td>${row.Artikelnummer}</td>
    <td>${row.Artikelname}</td>
    <td>${row.Lagerbestand}</td>
    <td>${row.BestandInAufträgen}</td>
    <td>${row.Verfuegbar}</td>
    <td>${row.Mindestbestand}</td>
    <td>${row.PufferZumSoll}</td>
  </tr>`;
}
html += "</table>";

const body = `<html><body><h3>Bericht | Merch-Mindestbestand:</h3><br>${html}</body></html>`;

return [{ json: { subject: "Bericht | Merch-Mindestbestand", html: body } }];

